const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const semver = require('C:/nvm4w/nodejs/node_modules/npm/node_modules/semver');
const read = name => JSON.parse(fs.readFileSync(path.join(__dirname, name), 'utf8'));
const checks = [];
for (const [file, expected] of [['next-config-fresh.json', true], ['react-fresh.json', false], ['import-fresh.json', false], ['a11y-fresh.json', false]]) {
  const m = read(file); const range = m.peerDependencies.eslint;
  const matches = semver.satisfies('10.13.0', range);
  assert.equal(matches, expected);
  checks.push({kind: 'ESLint peer declaration', package: m.name, version: m.version, range, candidate: '10.13.0', matches, expected});
}
const inv = read('inventory-results.json');
assert.equal(inv.entry_count, 31);
for (const item of inv.deprecated_entries) {
  assert(semver.gte('19.3.1', item.deprecated_since));
  checks.push({kind: 'React deprecation catalog threshold', key: item.key, since: item.deprecated_since, candidate: '19.3.1', matches: true});
}
const map = read('rule-map.json');
assert.equal(map.rows.length, 17); assert.equal(map.fixtures.length, 34);
assert.equal(new Set(map.fixtures.map(f => f.id)).size, 34);
assert(map.fixtures.every(f => f.status === 'not run'));
assert(map.rows.every(r => r.fixture_ids.every(id => map.fixtures.some(f => f.id === id))));
const result = {kind: 'range and data-shape assertions, not lint/compiler execution', runtime: process.version, semver: require('C:/nvm4w/nodejs/node_modules/npm/node_modules/semver/package.json').version, assertions: checks.length, matches: checks.filter(x => x.matches).length, expectedNonmatches: checks.filter(x => !x.matches).length, checks, mappedRules: 17, unexecutedSpecimens: 34};
fs.writeFileSync(path.join(__dirname, 'map-check-results.json'), JSON.stringify(result, null, 2) + '\n');
console.log(`PASS: ${checks.length} assertions (${result.matches} matches, ${result.expectedNonmatches} expected nonmatches); 17 rule rows / 34 unexecuted specimens; Node ${process.version}`);

from html.parser import HTMLParser
from pathlib import Path
class Visible(HTMLParser):
 def __init__(self):super().__init__();self.skip=0;self.parts=[]
 def handle_starttag(self,tag,attrs):
  if tag in ['script','style']:self.skip+=1
 def handle_endtag(self,tag):
  if tag in ['script','style']:self.skip-=1
 def handle_data(self,data):
  if not self.skip and data.strip():self.parts.append(data.strip())
r=Path(__file__).parent
for name in ['eslint-jsx-support','pnpm-peer-settings','ts-eslint-deprecated']:
 p=Visible();p.feed((r/(name+'.html')).read_text(encoding='utf-8'));(r/(name+'.txt')).write_text('\n'.join(p.parts)+'\n',encoding='utf-8')

import concurrent.futures,datetime,hashlib,json,pathlib,urllib.parse,urllib.request
