}
def fetch(item):
 name,url=item;r={'name':name,'url':url,'observed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  req=urllib.request.Request(url,headers={'User-Agent':'YourOwn-M00-T04-StaticResearch','Accept':'application/json' if 'registry.npmjs.org' in url else 'text/html'})
  with urllib.request.urlopen(req,timeout=40) as res:raw=res.read(8*1024*1024+1)
  assert len(raw)<=8*1024*1024
  ext='.json' if 'registry.npmjs.org' in url else '.html';(ROOT/(name+ext)).write_bytes(raw);r.update(file=name+ext,bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())
 except Exception as e:r['error']=type(e).__name__+': '+str(e)
 print(name,r.get('bytes',r.get('error')),flush=True);return r
with concurrent.futures.ThreadPoolExecutor(max_workers=5) as pool:rows=list(pool.map(fetch,JOBS.items()))
